-- Phase 7B: immutable launch publication and server-authoritative public ticket sales.
-- Forward-only/additive: existing festivals remain private and no money moves during migration.
CREATE TABLE public.festival_public_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid UNIQUE NOT NULL REFERENCES public.festival_companies(id),public_name text NOT NULL CHECK(char_length(btrim(public_name)) BETWEEN 3 AND 100),tagline text CHECK(char_length(tagline)<=180),description text NOT NULL CHECK(char_length(description) BETWEEN 20 AND 4000 AND description!~'<[^>]+>'),public_slug text UNIQUE NOT NULL CHECK(public_slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),hero_image_reference text,logo_reference text,age_guidance text CHECK(char_length(age_guidance)<=500),accessibility_summary text CHECK(char_length(accessibility_summary)<=2000),transport_summary text CHECK(char_length(transport_summary)<=2000),camping_summary text CHECK(char_length(camping_summary)<=2000),food_and_drink_summary text CHECK(char_length(food_and_drink_summary)<=2000),terms_summary text CHECK(char_length(terms_summary)<=3000),refund_policy_summary text CHECK(char_length(refund_policy_summary)<=3000),contact_summary text CHECK(char_length(contact_summary)<=1000),public_version integer NOT NULL DEFAULT 1 CHECK(public_version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_launches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid UNIQUE NOT NULL REFERENCES public.festival_companies(id),timetable_plan_id uuid UNIQUE NOT NULL REFERENCES public.festival_timetable_plans(id),readiness_snapshot_id uuid NOT NULL REFERENCES public.festival_readiness_snapshots(id),launch_status text NOT NULL DEFAULT 'ready_for_launch_preparation' CHECK(launch_status IN('ready_for_launch_preparation','launch_review','launched','tickets_on_sale','sales_paused','sales_closed','cancelled_before_event')),public_slug text UNIQUE,public_visibility text NOT NULL DEFAULT 'private' CHECK(public_visibility IN('private','unlisted','public')),launch_version integer NOT NULL DEFAULT 1 CHECK(launch_version>0),launch_requested_at timestamptz,launched_at timestamptz,ticket_sales_opened_at timestamptz,ticket_sales_closed_at timestamptz,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_launch_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),snapshot_version integer NOT NULL,configuration_snapshot jsonb NOT NULL,site_snapshot jsonb NOT NULL,stage_snapshot jsonb NOT NULL,ticket_snapshot jsonb NOT NULL,artist_snapshot jsonb NOT NULL,operations_snapshot jsonb NOT NULL,sponsorship_snapshot jsonb NOT NULL,timetable_snapshot jsonb NOT NULL,readiness_snapshot jsonb NOT NULL,finance_snapshot jsonb NOT NULL,public_snapshot jsonb NOT NULL,formula_versions jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by_profile_id uuid NOT NULL REFERENCES public.profiles(id),UNIQUE(festival_launch_id,snapshot_version));
CREATE TABLE public.festival_public_editions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid UNIQUE NOT NULL REFERENCES public.festival_launches(id),slug text UNIQUE NOT NULL,name text NOT NULL,tagline text,description text NOT NULL,city_id uuid NOT NULL REFERENCES public.cities(id),city_name text NOT NULL,country_name text NOT NULL,timezone text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,festival_type text,vibe text,scale text,hero_image_reference text,launch_status text NOT NULL,sold_out boolean NOT NULL DEFAULT false,public_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_public_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),source_stage_id uuid NOT NULL,name text NOT NULL,capacity integer NOT NULL CHECK(capacity>=0),sort_order integer NOT NULL,UNIQUE(festival_launch_id,source_stage_id));
CREATE TABLE public.festival_public_timetable(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),source_slot_id uuid UNIQUE NOT NULL,artist_name text NOT NULL,artist_type text NOT NULL CHECK(artist_type IN('player','band','npc')),artist_id uuid,genre text,fame integer NOT NULL DEFAULT 0,stage_id uuid NOT NULL REFERENCES public.festival_public_stages(id),festival_date date NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,headline boolean NOT NULL DEFAULT false,CHECK(starts_at<ends_at));
CREATE TABLE public.festival_public_sponsors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),source_contract_id uuid UNIQUE NOT NULL,sponsor_name text NOT NULL,logo_reference text,category text NOT NULL,relationship_label text NOT NULL,sponsored_area text);
CREATE TABLE public.festival_public_ticket_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),source_ticket_product_id uuid UNIQUE NOT NULL,name text NOT NULL,ticket_type text NOT NULL,product_class text NOT NULL CHECK(product_class IN('admission','upgrade','add_on')),access_scope text NOT NULL CHECK(access_scope IN('single_day','date_range','full_festival','non_admission')),access_start_date date NOT NULL,access_end_date date NOT NULL,price_minor bigint NOT NULL CHECK(price_minor>=0),currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),purchase_limit integer NOT NULL CHECK(purchase_limit>0),active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL);
CREATE TABLE public.festival_directory_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid UNIQUE NOT NULL REFERENCES public.festival_launches(id),public_edition_id uuid UNIQUE NOT NULL REFERENCES public.festival_public_editions(id),launched_at timestamptz NOT NULL,popularity_score integer NOT NULL DEFAULT 0,reputation_score integer NOT NULL DEFAULT 0);
CREATE TABLE public.festival_city_calendar_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid UNIQUE NOT NULL REFERENCES public.festival_launches(id),city_id uuid NOT NULL REFERENCES public.cities(id),name text NOT NULL,site_name text,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,public_route text NOT NULL,scale text,description text,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','cancelled')));
CREATE TABLE public.festival_countdowns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid UNIQUE NOT NULL REFERENCES public.festival_launches(id),target_at timestamptz NOT NULL,timezone text NOT NULL,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','cancelled','elapsed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_ticket_sale_phases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),source_planned_phase_id uuid,name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','disabled')),priority integer NOT NULL,UNIQUE(festival_launch_id,priority),CHECK(ends_at IS NULL OR starts_at<ends_at));
CREATE TABLE public.festival_ticket_inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),ticket_product_id uuid UNIQUE NOT NULL REFERENCES public.festival_public_ticket_products(id),capacity integer NOT NULL CHECK(capacity>=0),reserved_quantity integer NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0),sold_quantity integer NOT NULL DEFAULT 0 CHECK(sold_quantity>=0),cancelled_quantity integer NOT NULL DEFAULT 0 CHECK(cancelled_quantity>=0),refunded_quantity integer NOT NULL DEFAULT 0 CHECK(refunded_quantity>=0),available_quantity integer GENERATED ALWAYS AS (capacity-reserved_quantity-sold_quantity+cancelled_quantity+refunded_quantity) STORED,inventory_version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(capacity-reserved_quantity-sold_quantity+cancelled_quantity+refunded_quantity>=0));
CREATE TABLE public.festival_ticket_purchase_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_profile_id uuid NOT NULL REFERENCES public.profiles(id),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),ticket_product_id uuid NOT NULL REFERENCES public.festival_public_ticket_products(id),idempotency_key uuid NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'processing' CHECK(status IN('processing','completed')),result jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(buyer_profile_id,festival_launch_id,idempotency_key));
CREATE TABLE public.festival_ticket_sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),ticket_product_id uuid NOT NULL REFERENCES public.festival_public_ticket_products(id),buyer_profile_id uuid NOT NULL REFERENCES public.profiles(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_minor bigint NOT NULL,subtotal_minor bigint NOT NULL,fee_minor bigint NOT NULL,tax_minor bigint NOT NULL,total_minor bigint NOT NULL,currency text NOT NULL,status text NOT NULL CHECK(status IN('completed','cancelled','refunded','partially_refunded')),purchase_request_id uuid UNIQUE NOT NULL REFERENCES public.festival_ticket_purchase_requests(id),formula_versions jsonb NOT NULL,purchased_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,refunded_at timestamptz);
CREATE TABLE public.festival_issued_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_ticket_sale_id uuid REFERENCES public.festival_ticket_sales(id),ticket_product_id uuid NOT NULL REFERENCES public.festival_public_ticket_products(id),owner_profile_id uuid NOT NULL REFERENCES public.profiles(id),holder_profile_id uuid NOT NULL REFERENCES public.profiles(id),ticket_reference text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(24),'hex'),access_start_date date NOT NULL,access_end_date date NOT NULL,ticket_type text NOT NULL,status text NOT NULL DEFAULT 'valid' CHECK(status IN('valid','transferred','cancelled','refunded','used')),issued_at timestamptz NOT NULL DEFAULT now(),used_at timestamptz,cancelled_at timestamptz);
CREATE TABLE public.festival_complimentary_ticket_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),ticket_product_id uuid NOT NULL REFERENCES public.festival_public_ticket_products(id),reason text NOT NULL CHECK(reason IN('artist','staff','sponsor','media','VIP_guest','competition','admin')),capacity integer NOT NULL CHECK(capacity>=0),issued_quantity integer NOT NULL DEFAULT 0 CHECK(issued_quantity BETWEEN 0 AND capacity),UNIQUE(festival_launch_id,ticket_product_id,reason));
CREATE TABLE public.festival_launch_amendments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),amendment_type text NOT NULL CHECK(amendment_type IN('artist_replacement','performance_time_change','stage_change','ticket_sales_pause','public_information_update','sponsor_visibility_update','safety_update','festival_cancellation')),status text NOT NULL CHECK(status IN('proposed','approved','applied','rejected')),reason_code text NOT NULL,public_reason text,private_reason text,previous_snapshot jsonb NOT NULL,proposed_snapshot jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,applied_at timestamptz);
CREATE TABLE public.festival_ticket_refund_obligations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_ticket_sale_id uuid UNIQUE NOT NULL REFERENCES public.festival_ticket_sales(id),buyer_profile_id uuid NOT NULL REFERENCES public.profiles(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL,reason_code text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','completed','failed','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE public.festival_launch_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid NOT NULL REFERENCES public.festival_launches(id),event_type text NOT NULL,recipient_profile_id uuid REFERENCES public.profiles(id),channel text NOT NULL CHECK(channel IN('audit','mail','notification','world_pulse','twaater')),dedupe_key text UNIQUE NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_launch_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_launch_id uuid REFERENCES public.festival_launches(id),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),actor_profile_id uuid NOT NULL REFERENCES public.profiles(id),action text NOT NULL,idempotency_key uuid NOT NULL,payload_hash text NOT NULL,result jsonb,status text NOT NULL DEFAULT 'processing',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(actor_profile_id,action,idempotency_key));

CREATE FUNCTION public._festival_launch_authorised(c uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.festival_companies f WHERE f.id=c AND f.owner_profile_id=a) OR coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false)$$;
CREATE FUNCTION public._festival_launch_json(l public.festival_launches) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT jsonb_build_object('id',l.id,'festivalCompanyId',l.festival_company_id,'launchStatus',l.launch_status,'publicSlug',l.public_slug,'publicVisibility',l.public_visibility,'launchVersion',l.launch_version,'launchedAt',l.launched_at,'ticketSalesOpenedAt',l.ticket_sales_opened_at)$$;
CREATE FUNCTION public.save_festival_public_profile(p_festival_company_id uuid,p_expected_version integer,p_profile jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();r public.festival_public_profiles%ROWTYPE;BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden' USING ERRCODE='P0001';END IF;IF coalesce(p_profile->>'publicName','')='' OR coalesce(p_profile->>'description','')~'<[^>]+>' THEN RAISE EXCEPTION 'festival_public_profile_invalid' USING ERRCODE='P0001';END IF;INSERT INTO public.festival_public_profiles(festival_company_id,public_name,tagline,description,public_slug,hero_image_reference,logo_reference,age_guidance,accessibility_summary,transport_summary,camping_summary,food_and_drink_summary,terms_summary,refund_policy_summary,contact_summary) VALUES(p_festival_company_id,p_profile->>'publicName',p_profile->>'tagline',p_profile->>'description',p_profile->>'publicSlug',p_profile->>'heroImageReference',p_profile->>'logoReference',p_profile->>'ageGuidance',p_profile->>'accessibilitySummary',p_profile->>'transportSummary',p_profile->>'campingSummary',p_profile->>'foodAndDrinkSummary',p_profile->>'termsSummary',p_profile->>'refundPolicySummary',p_profile->>'contactSummary') ON CONFLICT(festival_company_id) DO UPDATE SET public_name=excluded.public_name,tagline=excluded.tagline,description=excluded.description,public_slug=excluded.public_slug,hero_image_reference=excluded.hero_image_reference,logo_reference=excluded.logo_reference,age_guidance=excluded.age_guidance,accessibility_summary=excluded.accessibility_summary,transport_summary=excluded.transport_summary,camping_summary=excluded.camping_summary,food_and_drink_summary=excluded.food_and_drink_summary,terms_summary=excluded.terms_summary,refund_policy_summary=excluded.refund_policy_summary,contact_summary=excluded.contact_summary,public_version=public.festival_public_profiles.public_version+1,updated_at=now() WHERE public.festival_public_profiles.public_version=p_expected_version RETURNING * INTO r;IF r.id IS NULL THEN RAISE EXCEPTION 'festival_public_profile_stale';END IF;RETURN to_jsonb(r);EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_public_slug_taken' USING ERRCODE='P0001';END$$;
CREATE FUNCTION public.begin_festival_launch_review(p_festival_company_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();t public.festival_timetable_plans%ROWTYPE;s public.festival_readiness_snapshots%ROWTYPE;l public.festival_launches%ROWTYPE;BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;SELECT * INTO t FROM public.festival_timetable_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF t.status<>'ready_for_launch_preparation' THEN RAISE EXCEPTION 'festival_launch_not_ready' USING ERRCODE='P0001';END IF;SELECT * INTO s FROM public.festival_readiness_snapshots WHERE festival_timetable_plan_id=t.id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;IF s.id IS NULL OR s.snapshot_version<>t.planning_version OR EXISTS(SELECT 1 FROM public.festival_schedule_conflicts WHERE festival_timetable_plan_id=t.id AND active AND blocking) THEN RAISE EXCEPTION 'festival_launch_snapshot_stale' USING ERRCODE='P0001';END IF;INSERT INTO public.festival_launches(festival_company_id,timetable_plan_id,readiness_snapshot_id,launch_status,launch_requested_at)VALUES(p_festival_company_id,t.id,s.id,'launch_review',now()) ON CONFLICT(festival_company_id) DO UPDATE SET launch_status='launch_review',launch_requested_at=now(),launch_version=public.festival_launches.launch_version+1,updated_at=now() WHERE public.festival_launches.launch_status='ready_for_launch_preparation' AND public.festival_launches.launch_version=p_expected_version RETURNING * INTO l;IF l.id IS NULL THEN RAISE EXCEPTION 'festival_launch_review_required';END IF;RETURN public._festival_launch_json(l);END$$;
CREATE FUNCTION public.launch_festival(p_festival_company_id uuid,p_expected_version integer,p_public_profile_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();l public.festival_launches%ROWTYPE;t public.festival_timetable_plans%ROWTYPE;s public.festival_readiness_snapshots%ROWTYPE;pp public.festival_public_profiles%ROWTYPE;cfg public.festival_configurations%ROWTYPE;sp public.festival_site_plans%ROWTYPE;tp public.festival_ticket_plans%ROWTYPE;ed uuid;result jsonb;BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;SELECT * INTO l FROM public.festival_launches WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF l.launch_status IN('launched','tickets_on_sale','sales_paused','sales_closed') THEN IF l.launch_version=p_expected_version THEN RETURN public._festival_launch_json(l);END IF;RAISE EXCEPTION 'festival_launch_already_completed';END IF;IF l.launch_status<>'launch_review' OR l.launch_version<>p_expected_version THEN RAISE EXCEPTION 'festival_launch_review_required' USING ERRCODE='P0001';END IF;SELECT * INTO t FROM public.festival_timetable_plans WHERE id=l.timetable_plan_id FOR UPDATE;SELECT * INTO s FROM public.festival_readiness_snapshots WHERE id=l.readiness_snapshot_id FOR UPDATE;SELECT * INTO pp FROM public.festival_public_profiles WHERE festival_company_id=p_festival_company_id FOR UPDATE;SELECT * INTO cfg FROM public.festival_configurations WHERE festival_company_id=p_festival_company_id FOR UPDATE;SELECT * INTO sp FROM public.festival_site_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;SELECT * INTO tp FROM public.festival_ticket_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF s.snapshot_version<>t.planning_version OR t.status<>'ready_for_launch_preparation' OR EXISTS(SELECT 1 FROM public.festival_schedule_conflicts WHERE festival_timetable_plan_id=t.id AND active AND blocking) THEN RAISE EXCEPTION 'festival_launch_snapshot_stale' USING ERRCODE='P0001';END IF;IF pp.id IS NULL OR pp.public_version<>p_public_profile_version THEN RAISE EXCEPTION 'festival_public_profile_invalid';END IF;IF cfg.planned_start_date<=current_date+7 OR tp.status<>'ready_for_artist_planning' OR NOT EXISTS(SELECT 1 FROM public.festival_ticket_products WHERE festival_ticket_plan_id=tp.id AND active AND product_class='admission' AND price_minor>=0) THEN RAISE EXCEPTION 'festival_launch_not_ready';END IF;
INSERT INTO public.festival_launch_snapshots(festival_launch_id,snapshot_version,configuration_snapshot,site_snapshot,stage_snapshot,ticket_snapshot,artist_snapshot,operations_snapshot,sponsorship_snapshot,timetable_snapshot,readiness_snapshot,finance_snapshot,public_snapshot,formula_versions,created_by_profile_id) SELECT l.id,l.launch_version,to_jsonb(cfg),to_jsonb(sp),coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_stages x WHERE x.festival_company_id=p_festival_company_id),'[]'),jsonb_build_object('plan',to_jsonb(tp),'products',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_ticket_products x WHERE x.festival_ticket_plan_id=tp.id),'[]')),coalesce((SELECT jsonb_agg(to_jsonb(x)-'suitability_snapshot'-'availability_snapshot') FROM public.festival_artist_performance_slots x WHERE x.festival_timetable_plan_id=t.id AND x.performance_status='scheduled'),'[]'),'{}','{}',public._festival_timetable_result(p_festival_company_id),to_jsonb(s),s.finance_snapshot,to_jsonb(pp),jsonb_build_object('launch',1,'readiness',t.readiness_formula_version,'ticketFees',1,'salesTax',1) ON CONFLICT DO NOTHING;
INSERT INTO public.festival_public_editions(festival_launch_id,slug,name,tagline,description,city_id,city_name,country_name,timezone,starts_at,ends_at,festival_type,vibe,scale,hero_image_reference,launch_status) SELECT l.id,pp.public_slug,pp.public_name,pp.tagline,pp.description,cfg.home_city_id,c.name,c.country,t.timezone,min(d.public_open_at),max(d.public_close_at),NULL,NULL,cfg.festival_scale,pp.hero_image_reference,'launched' FROM public.cities c,public.festival_timetable_days d WHERE c.id=cfg.home_city_id AND d.festival_timetable_plan_id=t.id GROUP BY c.name,c.country RETURNING id INTO ed;
INSERT INTO public.festival_public_stages(festival_launch_id,source_stage_id,name,capacity,sort_order) SELECT l.id,id,name,capacity,sort_order FROM public.festival_stages WHERE festival_company_id=p_festival_company_id AND status='ready';
INSERT INTO public.festival_public_timetable(festival_launch_id,source_slot_id,artist_name,artist_type,artist_id,genre,fame,stage_id,festival_date,starts_at,ends_at,headline) SELECT l.id,ss.id,coalesce(pr.display_name,b.name,'Festival artist'),CASE ps.artist_source WHEN 'profile' THEN 'player' ELSE ps.artist_source END,coalesce(ps.profile_id,ps.band_id,ps.npc_artist_id),NULL,coalesce(pr.fame,b.popularity,0),pub.id,d.festival_date,ss.starts_at,ss.ends_at,ss.headline_slot FROM public.festival_artist_performance_slots ps JOIN public.festival_stage_slots ss ON ss.id=ps.stage_slot_id JOIN public.festival_timetable_days d ON d.id=ss.festival_timetable_day_id JOIN public.festival_public_stages pub ON pub.source_stage_id=ss.stage_id LEFT JOIN public.profiles pr ON pr.id=ps.profile_id LEFT JOIN public.bands b ON b.id=ps.band_id WHERE ps.festival_timetable_plan_id=t.id AND ps.performance_status='scheduled' AND ss.slot_type='performance' AND ss.status='locked';
INSERT INTO public.festival_public_ticket_products(festival_launch_id,source_ticket_product_id,name,ticket_type,product_class,access_scope,access_start_date,access_end_date,price_minor,currency,purchase_limit,active,sort_order) SELECT l.id,p.id,p.name,p.ticket_type,p.product_class,p.access_scope,p.valid_from_date,p.valid_to_date,p.price_minor,tp.currency_code,tp.maximum_purchase_quantity,p.active,p.sale_priority FROM public.festival_ticket_products p WHERE p.festival_ticket_plan_id=tp.id AND p.active;
INSERT INTO public.festival_ticket_inventory(festival_launch_id,ticket_product_id,capacity,reserved_quantity) SELECT l.id,pub.id,p.capacity_limit,coalesce((SELECT sum(a.capacity_complimentary) FROM public.festival_ticket_capacity_allocations a WHERE a.festival_ticket_product_id=p.id),0) FROM public.festival_ticket_products p JOIN public.festival_public_ticket_products pub ON pub.source_ticket_product_id=p.id WHERE p.festival_ticket_plan_id=tp.id;
INSERT INTO public.festival_ticket_sale_phases(festival_launch_id,source_planned_phase_id,name,starts_at,ends_at,status,priority) SELECT l.id,r.id,r.name,coalesce(r.starts_at,now()),r.ends_at,CASE WHEN r.status='disabled' THEN 'disabled' ELSE 'scheduled' END,r.sort_order FROM public.festival_ticket_release_phases r WHERE r.festival_ticket_plan_id=tp.id;
INSERT INTO public.festival_directory_entries(festival_launch_id,public_edition_id,launched_at)VALUES(l.id,ed,now());INSERT INTO public.festival_city_calendar_events(festival_launch_id,city_id,name,site_name,starts_at,ends_at,public_route,scale,description)SELECT l.id,cfg.home_city_id,pp.public_name,sp.site_name,e.starts_at,e.ends_at,'/world/festivals/'||pp.public_slug,cfg.festival_scale,pp.description FROM public.festival_public_editions e WHERE e.id=ed;INSERT INTO public.festival_countdowns(festival_launch_id,target_at,timezone)SELECT l.id,starts_at,timezone FROM public.festival_public_editions WHERE id=ed;INSERT INTO public.festival_launch_events(festival_launch_id,event_type,recipient_profile_id,channel,dedupe_key,payload)VALUES(l.id,'festival_launched',a,'audit','festival-launch-audit-'||l.id,jsonb_build_object('route','/world/festivals/'||pp.public_slug)),(l.id,'festival_launched',a,'mail','festival-launch-owner-'||l.id,jsonb_build_object('route','/world/festivals/'||pp.public_slug)),(l.id,'festival_launched',NULL,'world_pulse','festival-launch-pulse-'||l.id,jsonb_build_object('formulaVersion',1,'public',true)),(l.id,'festival_launched',NULL,'twaater','festival-launch-twaater-'||l.id,jsonb_build_object('public',true));UPDATE public.festival_launches SET launch_status='launched',public_slug=pp.public_slug,public_visibility='public',launched_at=now(),launch_version=launch_version+1,updated_at=now() WHERE id=l.id RETURNING * INTO l;RETURN public._festival_launch_json(l);END$$;
CREATE FUNCTION public._festival_sales_transition(c uuid,expected integer,k uuid,target text,reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();l public.festival_launches%ROWTYPE;BEGIN IF NOT public._festival_launch_authorised(c,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;SELECT * INTO l FROM public.festival_launches WHERE festival_company_id=c FOR UPDATE;IF l.launch_version<>expected THEN RAISE EXCEPTION 'festival_ticket_purchase_stale';END IF;IF target='tickets_on_sale' AND l.launch_status NOT IN('launched','sales_paused') THEN RAISE EXCEPTION 'festival_ticket_sales_not_open';ELSIF target='sales_paused' AND l.launch_status<>'tickets_on_sale' THEN RAISE EXCEPTION 'festival_ticket_sales_not_open';ELSIF target='sales_closed' AND l.launch_status NOT IN('tickets_on_sale','sales_paused') THEN RAISE EXCEPTION 'festival_ticket_sales_closed';END IF;IF target='tickets_on_sale' AND NOT EXISTS(SELECT 1 FROM public.festival_ticket_inventory i JOIN public.festival_public_ticket_products p ON p.id=i.ticket_product_id WHERE i.festival_launch_id=l.id AND p.product_class='admission' AND p.active AND i.available_quantity>0) THEN RAISE EXCEPTION 'festival_ticket_product_unavailable';END IF;UPDATE public.festival_launches SET launch_status=target,launch_version=launch_version+1,ticket_sales_opened_at=CASE WHEN target='tickets_on_sale' THEN coalesce(ticket_sales_opened_at,now()) ELSE ticket_sales_opened_at END,ticket_sales_closed_at=CASE WHEN target='sales_closed' THEN now() ELSE ticket_sales_closed_at END,updated_at=now() WHERE id=l.id RETURNING * INTO l;INSERT INTO public.festival_launch_events(festival_launch_id,event_type,recipient_profile_id,channel,dedupe_key,payload)VALUES(l.id,target,a,'audit',target||'-audit-'||l.id||'-'||l.launch_version,jsonb_build_object('reason',reason)),(l.id,target,NULL,'world_pulse',target||'-pulse-'||l.id||'-'||l.launch_version,jsonb_build_object('public',true));RETURN public._festival_launch_json(l);END$$;
CREATE FUNCTION public.open_festival_ticket_sales(p_festival_company_id uuid,p_expected_launch_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_sales_transition(p_festival_company_id,p_expected_launch_version,p_idempotency_key,'tickets_on_sale')$$;
CREATE FUNCTION public.pause_festival_ticket_sales(p_festival_company_id uuid,p_expected_launch_version integer,p_reason text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF p_reason NOT IN('manual_review','capacity_review','safety_review','technical_issue','festival_change','admin_action') THEN RAISE EXCEPTION 'festival_ticket_pause_reason_invalid';END IF;RETURN public._festival_sales_transition(p_festival_company_id,p_expected_launch_version,p_idempotency_key,'sales_paused',p_reason);END$$;
CREATE FUNCTION public.resume_festival_ticket_sales(p_festival_company_id uuid,p_expected_launch_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_sales_transition(p_festival_company_id,p_expected_launch_version,p_idempotency_key,'tickets_on_sale')$$;
CREATE FUNCTION public.close_festival_ticket_sales(p_festival_company_id uuid,p_expected_launch_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_sales_transition(p_festival_company_id,p_expected_launch_version,p_idempotency_key,'sales_closed')$$;

CREATE FUNCTION public.purchase_festival_tickets(p_festival_launch_id uuid,p_ticket_product_id uuid,p_quantity integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE buyer uuid:=public._caller_profile_id();l public.festival_launches%ROWTYPE;p public.festival_public_ticket_products%ROWTYPE;i public.festival_ticket_inventory%ROWTYPE;plan public.festival_ticket_plans%ROWTYPE;fc public.festival_companies%ROWTYPE;r public.festival_ticket_purchase_requests%ROWTYPE;s public.festival_ticket_sales%ROWTYPE;subtotal bigint;fee bigint;tax bigint;total bigint;h text;tickets jsonb;BEGIN IF buyer IS NULL THEN RAISE EXCEPTION 'festival_ticket_sales_not_open';END IF;IF p_quantity<1 OR p_quantity>100 THEN RAISE EXCEPTION 'festival_ticket_quantity_invalid' USING ERRCODE='P0001';END IF;h:=encode(digest(jsonb_build_object('launch',p_festival_launch_id,'product',p_ticket_product_id,'quantity',p_quantity)::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended(buyer::text||p_idempotency_key::text,0));SELECT * INTO r FROM public.festival_ticket_purchase_requests WHERE buyer_profile_id=buyer AND festival_launch_id=p_festival_launch_id AND idempotency_key=p_idempotency_key FOR UPDATE;IF FOUND THEN IF r.payload_hash<>h THEN RAISE EXCEPTION 'festival_ticket_purchase_idempotency_conflict' USING ERRCODE='P0001';END IF;IF r.status='completed' THEN RETURN r.result;END IF;ELSE INSERT INTO public.festival_ticket_purchase_requests(buyer_profile_id,festival_launch_id,ticket_product_id,idempotency_key,payload_hash)VALUES(buyer,p_festival_launch_id,p_ticket_product_id,p_idempotency_key,h)RETURNING * INTO r;END IF;SELECT * INTO l FROM public.festival_launches WHERE id=p_festival_launch_id FOR SHARE;IF l.launch_status='sales_paused' THEN RAISE EXCEPTION 'festival_ticket_sales_paused';ELSIF l.launch_status='sales_closed' THEN RAISE EXCEPTION 'festival_ticket_sales_closed';ELSIF l.launch_status<>'tickets_on_sale' THEN RAISE EXCEPTION 'festival_ticket_sales_not_open';END IF;SELECT * INTO p FROM public.festival_public_ticket_products WHERE id=p_ticket_product_id AND festival_launch_id=l.id FOR SHARE;IF p.id IS NULL OR NOT p.active THEN RAISE EXCEPTION 'festival_ticket_product_unavailable';END IF;IF p_quantity>p.purchase_limit OR coalesce((SELECT sum(quantity) FROM public.festival_ticket_sales WHERE buyer_profile_id=buyer AND ticket_product_id=p.id AND status='completed'),0)+p_quantity>p.purchase_limit THEN RAISE EXCEPTION 'festival_ticket_purchase_limit_exceeded';END IF;IF NOT EXISTS(SELECT 1 FROM public.festival_ticket_sale_phases WHERE festival_launch_id=l.id AND status='scheduled' AND starts_at<=now() AND (ends_at IS NULL OR ends_at>now())) THEN RAISE EXCEPTION 'festival_ticket_phase_inactive';END IF;IF p.product_class IN('upgrade','add_on') AND NOT EXISTS(SELECT 1 FROM public.festival_issued_tickets it JOIN public.festival_public_ticket_products owned ON owned.id=it.ticket_product_id WHERE it.owner_profile_id=buyer AND owned.festival_launch_id=l.id AND owned.product_class='admission' AND it.status='valid') THEN RAISE EXCEPTION 'festival_ticket_product_unavailable';END IF;SELECT * INTO i FROM public.festival_ticket_inventory WHERE ticket_product_id=p.id FOR UPDATE;IF p.product_class='admission' AND i.available_quantity<p_quantity THEN RAISE EXCEPTION 'festival_ticket_sold_out';END IF;SELECT tp.* INTO plan FROM public.festival_ticket_plans tp JOIN public.festival_launches x ON x.festival_company_id=tp.festival_company_id WHERE x.id=l.id;SELECT * INTO fc FROM public.festival_companies WHERE id=l.festival_company_id FOR UPDATE;subtotal:=p.price_minor*p_quantity;fee:=CASE plan.booking_fee_mode WHEN 'fixed' THEN plan.booking_fee_minor*p_quantity WHEN 'percentage' THEN (subtotal*plan.booking_fee_basis_points+9999)/10000 WHEN 'combined' THEN plan.booking_fee_minor*p_quantity+(subtotal*plan.booking_fee_basis_points+9999)/10000 ELSE 0 END;tax:=((subtotal+fee)*plan.sales_tax_rate_basis_points+9999)/10000;total:=subtotal+fee+tax;BEGIN PERFORM public.finance_transfer('player',buyer,'company',fc.company_id,total,'ticket_sale','Festival ticket purchase','festival-ticket-'||r.id,'festival_ticket_purchase',r.id,buyer,jsonb_build_object('festivalLaunchId',l.id,'taxLiabilityMinor',tax,'formulaVersion',1));EXCEPTION WHEN OTHERS THEN IF SQLERRM ILIKE '%insufficient%' THEN RAISE EXCEPTION 'festival_ticket_insufficient_funds' USING ERRCODE='P0001';ELSE RAISE;END IF;END;INSERT INTO public.festival_ticket_sales(festival_launch_id,ticket_product_id,buyer_profile_id,quantity,unit_price_minor,subtotal_minor,fee_minor,tax_minor,total_minor,currency,status,purchase_request_id,formula_versions)VALUES(l.id,p.id,buyer,p_quantity,p.price_minor,subtotal,fee,tax,total,p.currency,'completed',r.id,jsonb_build_object('fee',1,'tax',1))RETURNING * INTO s;INSERT INTO public.festival_issued_tickets(festival_ticket_sale_id,ticket_product_id,owner_profile_id,holder_profile_id,access_start_date,access_end_date,ticket_type)SELECT s.id,p.id,buyer,buyer,p.access_start_date,p.access_end_date,p.ticket_type FROM generate_series(1,p_quantity);IF p.product_class='admission' THEN UPDATE public.festival_ticket_inventory SET sold_quantity=sold_quantity+p_quantity,inventory_version=inventory_version+1,updated_at=now() WHERE id=i.id RETURNING * INTO i;END IF;SELECT jsonb_agg(jsonb_build_object('id',x.id,'saleId',s.id,'productId',p.id,'festivalName',e.name,'festivalSlug',e.slug,'ticketReference',x.ticket_reference,'ticketType',x.ticket_type,'productClass',p.product_class,'accessStartDate',x.access_start_date,'accessEndDate',x.access_end_date,'ownerProfileId',x.owner_profile_id,'holderProfileId',x.holder_profile_id,'status',x.status,'issuedAt',x.issued_at)) INTO tickets FROM public.festival_issued_tickets x JOIN public.festival_public_editions e ON e.festival_launch_id=l.id WHERE x.festival_ticket_sale_id=s.id;r.result:=jsonb_build_object('saleId',s.id,'purchaseRequestId',r.id,'status','completed','quantity',p_quantity,'subtotalMinor',subtotal,'feeMinor',fee,'taxMinor',tax,'totalMinor',total,'currency',p.currency,'inventoryVersion',coalesce(i.inventory_version,1),'availableQuantity',coalesce(i.available_quantity,0),'tickets',tickets);UPDATE public.festival_ticket_purchase_requests SET status='completed',result=r.result,completed_at=now() WHERE id=r.id;INSERT INTO public.festival_launch_events(festival_launch_id,event_type,recipient_profile_id,channel,dedupe_key,payload)VALUES(l.id,'ticket_purchase_completed',buyer,'mail','ticket-purchase-mail-'||r.id,r.result),(l.id,'ticket_purchase_completed',buyer,'notification','ticket-purchase-notification-'||r.id,jsonb_build_object('route','/tickets'));RETURN r.result;END$$;
CREATE FUNCTION public.issue_festival_complimentary_tickets(p_festival_company_id uuid,p_ticket_product_id uuid,p_recipient_profile_id uuid,p_quantity integer,p_reason text,p_expected_launch_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();l public.festival_launches%ROWTYPE;p public.festival_public_ticket_products%ROWTYPE;i public.festival_ticket_inventory%ROWTYPE;al public.festival_complimentary_ticket_allocations%ROWTYPE;BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;SELECT * INTO l FROM public.festival_launches WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF l.launch_version<>p_expected_launch_version OR l.launch_status NOT IN('launched','tickets_on_sale','sales_paused') THEN RAISE EXCEPTION 'festival_ticket_purchase_stale';END IF;SELECT * INTO p FROM public.festival_public_ticket_products WHERE id=p_ticket_product_id AND festival_launch_id=l.id;SELECT * INTO i FROM public.festival_ticket_inventory WHERE ticket_product_id=p.id FOR UPDATE;SELECT * INTO al FROM public.festival_complimentary_ticket_allocations WHERE festival_launch_id=l.id AND ticket_product_id=p.id AND reason=p_reason FOR UPDATE;IF p_quantity<1 OR al.id IS NULL OR al.issued_quantity+p_quantity>al.capacity OR i.reserved_quantity<p_quantity THEN RAISE EXCEPTION 'festival_complimentary_allocation_exceeded';END IF;INSERT INTO public.festival_issued_tickets(ticket_product_id,owner_profile_id,holder_profile_id,access_start_date,access_end_date,ticket_type)SELECT p.id,p_recipient_profile_id,p_recipient_profile_id,p.access_start_date,p.access_end_date,p.ticket_type FROM generate_series(1,p_quantity);UPDATE public.festival_complimentary_ticket_allocations SET issued_quantity=issued_quantity+p_quantity WHERE id=al.id;UPDATE public.festival_ticket_inventory SET reserved_quantity=reserved_quantity-p_quantity,sold_quantity=sold_quantity+p_quantity,inventory_version=inventory_version+1 WHERE id=i.id;INSERT INTO public.festival_launch_events(festival_launch_id,event_type,recipient_profile_id,channel,dedupe_key,payload)VALUES(l.id,'complimentary_ticket_issued',p_recipient_profile_id,'notification','festival-comp-'||p_idempotency_key,jsonb_build_object('quantity',p_quantity));RETURN jsonb_build_object('launch',public._festival_launch_json(l),'message','complimentary_tickets_issued','idempotent',false);END$$;
CREATE FUNCTION public.cancel_launched_festival(p_festival_company_id uuid,p_expected_launch_version integer,p_reason text,p_confirmation_token text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();l public.festival_launches%ROWTYPE;BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) OR char_length(btrim(p_reason))<10 OR p_confirmation_token<>'CANCEL FESTIVAL' THEN RAISE EXCEPTION 'festival_cancellation_not_permitted';END IF;SELECT * INTO l FROM public.festival_launches WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF l.launch_version<>p_expected_launch_version OR l.launch_status NOT IN('launch_review','launched','tickets_on_sale','sales_paused') THEN RAISE EXCEPTION 'festival_cancellation_not_permitted';END IF;UPDATE public.festival_launches SET launch_status='cancelled_before_event',public_visibility='public',ticket_sales_closed_at=coalesce(ticket_sales_closed_at,now()),cancelled_at=now(),launch_version=launch_version+1,updated_at=now() WHERE id=l.id RETURNING * INTO l;UPDATE public.festival_public_editions SET launch_status='cancelled_before_event' WHERE festival_launch_id=l.id;UPDATE public.festival_city_calendar_events SET status='cancelled' WHERE festival_launch_id=l.id;UPDATE public.festival_countdowns SET status='cancelled',updated_at=now() WHERE festival_launch_id=l.id;INSERT INTO public.festival_ticket_refund_obligations(festival_ticket_sale_id,buyer_profile_id,amount_minor,currency,reason_code)SELECT id,buyer_profile_id,total_minor,currency,'festival_cancelled' FROM public.festival_ticket_sales WHERE festival_launch_id=l.id AND status='completed' ON CONFLICT DO NOTHING;INSERT INTO public.festival_launch_events(festival_launch_id,event_type,recipient_profile_id,channel,dedupe_key,payload)SELECT l.id,'festival_cancelled',buyer_profile_id,'mail','festival-cancel-holder-'||id,jsonb_build_object('refundStatus','pending','reason',p_reason) FROM public.festival_ticket_sales WHERE festival_launch_id=l.id AND status='completed';INSERT INTO public.festival_launch_events(festival_launch_id,event_type,channel,dedupe_key,payload)VALUES(l.id,'festival_cancelled','world_pulse','festival-cancel-pulse-'||l.id,jsonb_build_object('publicReason',p_reason));RETURN public._festival_launch_json(l);END$$;
CREATE FUNCTION public.get_festival_launch_plan(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._caller_profile_id();BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;RETURN jsonb_build_object('launch',(SELECT public._festival_launch_json(x) FROM public.festival_launches x WHERE x.festival_company_id=p_festival_company_id),'publicProfile',(SELECT to_jsonb(x) FROM public.festival_public_profiles x WHERE x.festival_company_id=p_festival_company_id),'blockingIssues',coalesce((SELECT jsonb_agg(jsonb_build_object('code',code,'message',message_key)) FROM public.festival_schedule_conflicts c JOIN public.festival_timetable_plans t ON t.id=c.festival_timetable_plan_id WHERE t.festival_company_id=p_festival_company_id AND c.active AND c.blocking),'[]'::jsonb));END$$;
CREATE FUNCTION public.get_public_festival(p_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('id',e.id,'slug',e.slug,'name',e.name,'tagline',e.tagline,'description',e.description,'city',e.city_name,'country',e.country_name,'timezone',e.timezone,'startsAt',e.starts_at,'endsAt',e.ends_at,'festivalType',e.festival_type,'vibe',e.vibe,'scale',e.scale,'heroImageReference',e.hero_image_reference,'launchStatus',e.launch_status,'soldOut',e.sold_out,'countdownTarget',c.target_at,'stages',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'capacity',s.capacity) ORDER BY s.sort_order) FROM public.festival_public_stages s WHERE s.festival_launch_id=e.festival_launch_id),'[]'),'timetable',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'artistName',x.artist_name,'artistType',x.artist_type,'artistId',x.artist_id,'genre',x.genre,'fame',x.fame,'stageId',x.stage_id,'stageName',s.name,'festivalDate',x.festival_date,'startsAt',x.starts_at,'endsAt',x.ends_at,'headline',x.headline) ORDER BY x.starts_at) FROM public.festival_public_timetable x JOIN public.festival_public_stages s ON s.id=x.stage_id WHERE x.festival_launch_id=e.festival_launch_id),'[]'),'sponsors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'name',x.sponsor_name,'logoReference',x.logo_reference,'category',x.category,'relationshipLabel',x.relationship_label,'sponsoredArea',x.sponsored_area)) FROM public.festival_public_sponsors x WHERE x.festival_launch_id=e.festival_launch_id),'[]'),'ticketProducts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'ticketType',p.ticket_type,'productClass',p.product_class,'accessScope',p.access_scope,'accessStartDate',p.access_start_date,'accessEndDate',p.access_end_date,'priceMinor',p.price_minor,'feeMinor',0,'taxMinor',0,'totalMinor',p.price_minor,'currency',p.currency,'availableQuantity',i.available_quantity,'purchaseLimit',p.purchase_limit,'saleStatus',l.launch_status) ORDER BY p.sort_order) FROM public.festival_public_ticket_products p JOIN public.festival_ticket_inventory i ON i.ticket_product_id=p.id WHERE p.festival_launch_id=e.festival_launch_id AND p.active),'[]'),'information',jsonb_build_object('travel',pp.transport_summary,'camping',pp.camping_summary,'accessibility',pp.accessibility_summary,'foodAndDrink',pp.food_and_drink_summary,'ageGuidance',pp.age_guidance,'terms',pp.terms_summary,'refundPolicy',pp.refund_policy_summary,'contact',pp.contact_summary)) FROM public.festival_public_editions e JOIN public.festival_launches l ON l.id=e.festival_launch_id JOIN public.festival_public_profiles pp ON pp.festival_company_id=l.festival_company_id JOIN public.festival_countdowns c ON c.festival_launch_id=l.id WHERE e.slug=p_slug AND l.public_visibility='public'$$;
CREATE FUNCTION public.get_public_festival_directory(p_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(public.get_public_festival(e.slug) ORDER BY e.starts_at),'[]') FROM public.festival_public_editions e JOIN public.festival_launches l ON l.id=e.festival_launch_id WHERE l.public_visibility='public' AND (p_filters->>'city' IS NULL OR e.city_name=p_filters->>'city') AND (p_filters->>'country' IS NULL OR e.country_name=p_filters->>'country')$$;
CREATE FUNCTION public.get_public_festival_timetable(p_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce((public.get_public_festival(p_slug))->'timetable','[]')$$;
CREATE FUNCTION public.get_public_festival_ticket_products(p_festival_launch_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce((public.get_public_festival(e.slug))->'ticketProducts','[]') FROM public.festival_public_editions e WHERE e.festival_launch_id=p_festival_launch_id$$;
CREATE FUNCTION public.get_my_festival_tickets() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'saleId',t.festival_ticket_sale_id,'productId',t.ticket_product_id,'festivalName',e.name,'festivalSlug',e.slug,'ticketReference',t.ticket_reference,'ticketType',t.ticket_type,'productClass',p.product_class,'accessStartDate',t.access_start_date,'accessEndDate',t.access_end_date,'ownerProfileId',t.owner_profile_id,'holderProfileId',t.holder_profile_id,'status',t.status,'issuedAt',t.issued_at) ORDER BY t.access_start_date),'[]') FROM public.festival_issued_tickets t JOIN public.festival_public_ticket_products p ON p.id=t.ticket_product_id JOIN public.festival_public_editions e ON e.festival_launch_id=p.festival_launch_id WHERE t.owner_profile_id=public._caller_profile_id()$$;
CREATE FUNCTION public.get_festival_ticket_sales_summary(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE l uuid;a uuid:=public._caller_profile_id();BEGIN IF NOT public._festival_launch_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_launch_forbidden';END IF;SELECT id INTO l FROM public.festival_launches WHERE festival_company_id=p_festival_company_id;RETURN jsonb_build_object('festivalLaunchId',l,'currency',coalesce((SELECT currency FROM public.festival_public_ticket_products WHERE festival_launch_id=l LIMIT 1),'GBP'),'ticketsSold',coalesce((SELECT sum(sold_quantity) FROM public.festival_ticket_inventory WHERE festival_launch_id=l),0),'ticketsAvailable',coalesce((SELECT sum(available_quantity) FROM public.festival_ticket_inventory WHERE festival_launch_id=l),0),'grossSalesMinor',coalesce((SELECT sum(total_minor) FROM public.festival_ticket_sales WHERE festival_launch_id=l AND status='completed'),0),'feesMinor',coalesce((SELECT sum(fee_minor) FROM public.festival_ticket_sales WHERE festival_launch_id=l AND status='completed'),0),'taxLiabilityMinor',coalesce((SELECT sum(tax_minor) FROM public.festival_ticket_sales WHERE festival_launch_id=l AND status='completed'),0),'netFestivalReceiptsMinor',coalesce((SELECT sum(subtotal_minor) FROM public.festival_ticket_sales WHERE festival_launch_id=l AND status='completed'),0),'sellThroughBasisPoints',0,'products','[]'::jsonb);END$$;
CREATE FUNCTION public._reject_festival_launch_snapshot_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'festival_launch_snapshot_immutable' USING ERRCODE='P0001';END$$;
CREATE TRIGGER festival_launch_snapshots_immutable BEFORE UPDATE OR DELETE ON public.festival_launch_snapshots FOR EACH ROW EXECUTE FUNCTION public._reject_festival_launch_snapshot_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_public_profiles','festival_launches','festival_launch_snapshots','festival_public_editions','festival_public_stages','festival_public_timetable','festival_public_sponsors','festival_public_ticket_products','festival_directory_entries','festival_city_calendar_events','festival_countdowns','festival_ticket_sale_phases','festival_ticket_inventory','festival_ticket_purchase_requests','festival_ticket_sales','festival_issued_tickets','festival_complimentary_ticket_allocations','festival_launch_amendments','festival_ticket_refund_obligations','festival_launch_events','festival_launch_requests'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);END LOOP;END$$;
CREATE POLICY festival_public_editions_read ON public.festival_public_editions FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.festival_launches l WHERE l.id=festival_launch_id AND l.public_visibility='public'));
CREATE POLICY festival_issued_tickets_owner_read ON public.festival_issued_tickets FOR SELECT TO authenticated USING(owner_profile_id=public._caller_profile_id());
CREATE POLICY festival_ticket_sales_buyer_read ON public.festival_ticket_sales FOR SELECT TO authenticated USING(buyer_profile_id=public._caller_profile_id());
REVOKE ALL ON FUNCTION public._festival_launch_authorised(uuid,uuid),public._festival_launch_json(public.festival_launches),public._festival_sales_transition(uuid,integer,uuid,text,text),public._reject_festival_launch_snapshot_mutation() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_public_festival(text),public.get_public_festival_directory(jsonb),public.get_public_festival_timetable(text),public.get_public_festival_ticket_products(uuid) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_launch_plan(uuid),public.save_festival_public_profile(uuid,integer,jsonb,uuid),public.begin_festival_launch_review(uuid,integer,uuid),public.launch_festival(uuid,integer,integer,uuid),public.open_festival_ticket_sales(uuid,integer,uuid),public.pause_festival_ticket_sales(uuid,integer,text,uuid),public.resume_festival_ticket_sales(uuid,integer,uuid),public.close_festival_ticket_sales(uuid,integer,uuid),public.purchase_festival_tickets(uuid,uuid,integer,uuid),public.issue_festival_complimentary_tickets(uuid,uuid,uuid,integer,text,integer,uuid),public.cancel_launched_festival(uuid,integer,text,text,uuid),public.get_festival_ticket_sales_summary(uuid),public.get_my_festival_tickets() TO authenticated;
COMMENT ON TABLE public.festival_launch_snapshots IS 'Append-only server-generated launched-state record; private negotiations and mutable drafts are excluded.';
COMMENT ON FUNCTION public.purchase_festival_tickets(uuid,uuid,integer,uuid) IS 'Atomic capacity-locked purchase using canonical double-entry finance_transfer; totals are server-derived.';
